#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# The temestudo.cloud deploy steps only the maintainer does (#25,
# `docs/deploy.md`). Run from the repository root:
#
#   bash frontend/scripts/deploy-wizard.sh
#
# Keeps the IP, the user, the port, the key path and the e-mail in
# `.env.deploy` (gitignored), and can run again: Enter keeps the previous
# run's value. The private key only leaves the disk for the secret.

TOTAL_STAGES=8

cd "$(dirname "$0")/../.."
ENV_FILE=.env.deploy

# The YgorPerez account and this repository for `gh` (AGENTS.md), whatever
# the active account or the checkout's remote.
GH_TOKEN=$(gh auth token --user YgorPerez 2>/dev/null || true)
export GH_TOKEN
export GH_REPO=YgorPerez/pesquisa-relacionamentos

DEFAULT_KEY="$HOME/.ssh/temestudo-deploy"

banner "Deploy of temestudo.cloud"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "The VPS at Hostinger"
say "The site runs on a VPS of its own, never on the Festival dos Macacos one."
open_url "https://hpanel.hostinger.com/vps"
step "Hire or pick the Tem estudo? VPS (the cheapest plan is enough)."
step "Operating system: plain Ubuntu 26.04, no panel and no app."
step "Set the root password. The SSH key comes in stage 3."
step "In the VPS overview, copy the IPv4 address."
note "If the panel looks different, what matters is: Ubuntu 26.04, root access, and the IPv4."
ask VPS_HOST "VPS IPv4:"
[[ "$VPS_HOST" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || warn "That does not look like an IPv4: check before going on."
ask VPS_USER "SSH user (empty Enter = root):"
VPS_USER=${VPS_USER:-root}
ask VPS_PORT "SSH port (empty Enter = 22):"
VPS_PORT=${VPS_PORT:-22}
write_env VPS_HOST "$VPS_HOST"
write_env VPS_USER "$VPS_USER"
write_env VPS_PORT "$VPS_PORT"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The DNS at Hostinger"
say "The domain was bought at Hostinger and the DNS lives there. Three A records point to $VPS_HOST."
say "Certbot validates the domain right on the VPS, so no name can point elsewhere."
open_url "https://hpanel.hostinger.com/domains"
step "Open temestudo.cloud → DNS / Nameservers → DNS records."
note "The nameservers must be Hostinger's (ns1/ns2.dns-parking.com), or the records here do not count."
step "A record named @: edit it to point to $VPS_HOST (it comes pointing to the parking page)."
step "Name www: delete the ready-made CNAME and create an A, name www, pointing to $VPS_HOST."
step "Create an A, name stats, pointing to $VPS_HOST (GoatCounter uses it)."
step "Delete any AAAA on @, www or stats: Let's Encrypt would try IPv6 first."
note "Keep the TTL the panel suggests."
pause "Enter after saving the three records."
if command -v dig >/dev/null 2>&1; then
  for name in temestudo.cloud www.temestudo.cloud stats.temestudo.cloud; do
    seen=$(dig +short A "$name" @1.1.1.1 | tail -n1)
    if [[ "$seen" == "$VPS_HOST" ]]; then say "✓ $name → $seen"
    else warn "$name still answers '${seen:-nothing}'. It may take a few minutes; stage 5 needs it right."; fi
  done
else
  note "No dig here: check at https://dnschecker.org that temestudo.cloud points to $VPS_HOST."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The deploy SSH key"
say "A key only for GitHub Actions to get into the VPS, with no password."
ask VPS_SSH_KEY_PATH "Key path (empty Enter = $DEFAULT_KEY):"
VPS_SSH_KEY_PATH=${VPS_SSH_KEY_PATH:-$DEFAULT_KEY}
write_env VPS_SSH_KEY_PATH "$VPS_SSH_KEY_PATH"
if [[ -f "$VPS_SSH_KEY_PATH" ]]; then
  say "The key $VPS_SSH_KEY_PATH already exists: it stays as it is."
elif confirm "Generate the ed25519 key at $VPS_SSH_KEY_PATH, with no passphrase?"; then
  mkdir -p "$(dirname "$VPS_SSH_KEY_PATH")"
  ssh-keygen -t ed25519 -N "" -C "deploy temestudo.cloud" -f "$VPS_SSH_KEY_PATH" >/dev/null
  say "✓ key generated."
else
  warn "No key, no deploy. Run the wizard again when you want to generate it."
  exit 1
fi
say "Now the VPS needs to accept this key. ssh-copy-id asks for the root password once."
if confirm "Run ssh-copy-id for $VPS_USER@$VPS_HOST?"; then
  ssh-copy-id -i "$VPS_SSH_KEY_PATH.pub" -p "$VPS_PORT" -o StrictHostKeyChecking=accept-new "$VPS_USER@$VPS_HOST"
else
  note "Or paste the public key below into the Hostinger panel (VPS → SSH keys):"
  cat "$VPS_SSH_KEY_PATH.pub"
  pause "Enter after adding it."
fi
if ssh -i "$VPS_SSH_KEY_PATH" -o IdentitiesOnly=yes -o BatchMode=yes -o StrictHostKeyChecking=accept-new \
     -p "$VPS_PORT" "$VPS_USER@$VPS_HOST" true; then
  say "✓ the key gets into the VPS with no password."
else
  warn "The key does not get in yet. Check the step above and run the wizard again."
  exit 1
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The certificate e-mail"
say "Let's Encrypt sends the certificate expiry notices to it."
ask CERTBOT_EMAIL "E-mail:"
write_env CERTBOT_EMAIL "$CERTBOT_EMAIL"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Prepare the VPS"
say "frontend/scripts/prepare-vps.sh installs Docker, Nginx and certbot, opens 80 and 443"
say "and gets the certificate for temestudo.cloud, www and stats by webroot."
note "Needs stage 2's DNS already pointing to $VPS_HOST. It can run again without harm."
if confirm "Run prepare-vps.sh on $VPS_USER@$VPS_HOST now?"; then
  ssh -i "$VPS_SSH_KEY_PATH" -o IdentitiesOnly=yes -o BatchMode=yes -p "$VPS_PORT" \
    "$VPS_USER@$VPS_HOST" "bash -s -- '$CERTBOT_EMAIL'" < frontend/scripts/prepare-vps.sh
  say "✓ VPS ready."
else
  SKIPPED+=("prepare the VPS: ssh $VPS_USER@$VPS_HOST 'bash -s -- <email>' < frontend/scripts/prepare-vps.sh")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The GitHub Actions secrets"
say "The Deploy workflow (.github/workflows/deploy.yml) reads four secrets from the $GH_REPO repo."
[[ -n "$GH_TOKEN" ]] || warn "gh does not have the YgorPerez account: run 'gh auth login' with it first."
set_secret VPS_HOST "$VPS_HOST"
set_secret VPS_USER "$VPS_USER"
set_secret VPS_PORT "$VPS_PORT"
set_secret VPS_SSH_KEY "$(cat "$VPS_SSH_KEY_PATH")"
say "The first deploy creates the GoatCounter login with this e-mail and a random password."
ask STATS_EMAIL "GoatCounter login e-mail (empty Enter = admin@temestudo.cloud):"
STATS_EMAIL=${STATS_EMAIL:-admin@temestudo.cloud}
write_env STATS_EMAIL "$STATS_EMAIL"
set_var GOATCOUNTER_EMAIL "$STATS_EMAIL"
open_url "https://github.com/$GH_REPO/settings/secrets/actions"
note "Check on the page that VPS_HOST, VPS_USER, VPS_PORT and VPS_SSH_KEY are there, and GOATCOUNTER_EMAIL in the Variables tab."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The first deploy"
say "From here on each merge to main publishes by itself. The first one can go now,"
say "through the Deploy's 'Run workflow', as long as deploy.yml is already on main."
if confirm "Trigger the Deploy workflow on main now?"; then
  if gh workflow run deploy.yml --ref main >/dev/null; then
    say "✓ triggered."
  else
    SKIPPED+=("trigger the Deploy: gh workflow run deploy.yml --ref main")
  fi
fi
open_url "https://github.com/$GH_REPO/actions/workflows/deploy.yml"
pause "Enter when the run finishes green."
if curl -fsS -D - -o /dev/null https://temestudo.cloud/ 2>/dev/null | grep -qi '^referrer-policy: strict-origin'; then
  say "✓ https://temestudo.cloud answers, with Referrer-Policy: strict-origin."
else
  warn "https://temestudo.cloud does not answer as it should yet. See the run's log and docs/deploy.md."
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "The GoatCounter login"
say "The deploy created the stats.temestudo.cloud site and the $STATS_EMAIL login, with a random password"
say "in /opt/temestudo/goatcounter-senha, and turned on only referrer, screen and country, with 31 days."
note "Run this stage after the first green deploy."
SSH_VPS=(ssh -i "$VPS_SSH_KEY_PATH" -o IdentitiesOnly=yes -o BatchMode=yes -p "$VPS_PORT" "$VPS_USER@$VPS_HOST")
if STATS_PASSWORD=$("${SSH_VPS[@]}" "cat /opt/temestudo/goatcounter-senha" 2>/dev/null); then
  say "The password (keep it in your password manager):"
  printf '\n    %s%s%s\n\n' "$BOLD" "$STATS_PASSWORD" "$RESET"
else
  warn "The VPS does not have /opt/temestudo/goatcounter-senha. See the deploy log on the GoatCounter line."
  SKIPPED+=("GoatCounter login: the deploy did not write the password; see docs/deploy.md, GoatCounter section")
fi
open_url "https://stats.temestudo.cloud/settings/main"
step "Log in with $STATS_EMAIL and the password above. Under User → Password you can change it."
step "Under Settings → Data collection, check: Referrer, Size and Country checked; Sessions and the rest unchecked."
step "Under Data retention, check 31 days."
pause "Enter after checking."

finish
